begin;
create extension if not exists pgtap with schema extensions;
select no_plan();
create temp table signal_access_baseline as select encode(extensions.digest(coalesce(jsonb_agg(to_jsonb(a) order by a.id)::text,'[]'),'sha256'),'hex') hash from public.channel_access a;
\ir helpers/signal_fixtures.sql
create temp table signal_results(v jsonb);
insert into signal_results values(private.signal_record_fixture_v1(pg_temp.signal_input()));
select is((select v->>'duplicate' from signal_results),'false','first event persisted');
select is((select count(*)::int from private.signal_events where tenant_id='51a02000-0000-4000-8000-000000000001'),1,'one immutable event');
select is((select original#>>'{interpretation,entry,0}' from private.signal_events where tenant_id='51a02000-0000-4000-8000-000000000001'),'2700.010','precision preserved');
select is(private.signal_record_fixture_v1(pg_temp.signal_input())->>'duplicate','true','identical replay suppressed');
select is((select count(*)::int from private.signal_events where tenant_id='51a02000-0000-4000-8000-000000000001'),1,'replay does not append duplicate');
select is(private.signal_record_fixture_v1(replace(pg_temp.signal_input(),'18:00:00Z','18:00:01Z'))->>'duplicate','true','new arrival time is not a contradictory source event');
select throws_ok($$select private.signal_record_fixture_v1(replace(pg_temp.signal_input(),'2700.010','2701.010'))$$,'22023','SIGNAL_REPLAY_CONFLICT','same source/revision cannot change historical facts');
select lives_ok($$select private.signal_record_fixture_v1(pg_temp.signal_input('m1',3,'51a03000-0000-4000-8000-000000000001','51a02000-0000-4000-8000-000000000001','EDIT'))$$,'edit stored');
select is(private.signal_record_fixture_v1(pg_temp.signal_input('m1',2))->>'current','false','out of order earlier revision preserved but not current');
select is((select revision from private.signal_heads where tenant_id='51a02000-0000-4000-8000-000000000001' and message_key='m1'),3,'latest head monotonic');
select is((select count(*)::int from private.signal_events where tenant_id='51a02000-0000-4000-8000-000000000001'),3,'all legitimate revisions retained');
select lives_ok($$select private.signal_record_fixture_v1(pg_temp.signal_input('m1',1,'51a03000-0000-4000-8000-000000000002'))$$,'second source routes to same destination independently');
select is((select count(*)::int from private.signal_heads where tenant_id='51a02000-0000-4000-8000-000000000001'),2,'source identities independent');
select lives_ok($$select private.signal_record_fixture_v1(pg_temp.signal_input('restricted',1,'51a03000-0000-4000-8000-000000000001','51a02000-0000-4000-8000-000000000001','RESTRICTED'))$$,'restriction is durable evidence');
select is((select original->'original_text' from private.signal_events where tenant_id='51a02000-0000-4000-8000-000000000001' and message_key='restricted'),'null'::jsonb,'protected content not extracted');
select is((select parse_state from private.signal_events where tenant_id='51a02000-0000-4000-8000-000000000001' and message_key='restricted'),'UNAVAILABLE','restriction not reported successful');
select lives_ok($$select private.signal_record_fixture_v1(pg_temp.signal_input('deleted',1,'51a03000-0000-4000-8000-000000000001','51a02000-0000-4000-8000-000000000001','DELETE'))$$,'deletion retained');
select throws_ok($$select private.signal_record_fixture_v1(replace(pg_temp.signal_input(),'"version": 1','"version": 1,"version": 1'))$$,'22023','FSE_INVALID','duplicate keys rejected before jsonb');
select throws_ok($$select private.signal_record_fixture_v1(jsonb_set(pg_temp.signal_input()::jsonb,'{interpretation,entry}','[1.5]')::text)$$,'22023','SIGNAL_INVALID','numeric price authority denied');
select throws_ok($$select private.signal_record_fixture_v1(jsonb_set(pg_temp.signal_input()::jsonb,'{interpretation,entry}','[null]')::text)$$,'22023','SIGNAL_INVALID','null target is missing evidence, never a price');
select throws_ok($$select private.signal_record_fixture_v1(jsonb_set(pg_temp.signal_input()::jsonb,'{financial_authority}','"LIVE"')::text)$$,'22023','SIGNAL_INVALID','unexpected authority denied');
select throws_ok($$select private.signal_record_fixture_v1(pg_temp.signal_input('cross',1,'51a03000-0000-4000-8000-000000000003'))$$,'42501','signal scope unavailable','foreign source denied');
select throws_ok($$update private.signal_events set revision=99 where tenant_id='51a02000-0000-4000-8000-000000000001'$$,'42501','FSE_IMMUTABLE','event updates forbidden');
select throws_ok($$delete from private.signal_events where tenant_id='51a02000-0000-4000-8000-000000000001'$$,'42501','FSE_IMMUTABLE','event deletion forbidden');
update private.signal_providers set paused=true where id='51a04000-0000-4000-8000-000000000001';
select throws_ok($$select private.signal_record_fixture_v1(pg_temp.signal_input('paused'))$$,'42501','signal scope unavailable','provider kill switch');
update private.signal_providers set paused=false,authorization_status='REVOKED' where id='51a04000-0000-4000-8000-000000000001';
select throws_ok($$select private.signal_record_fixture_v1(pg_temp.signal_input('revoked'))$$,'42501','signal scope unavailable','revoked rights fail closed');
update private.signal_providers set authorization_status='SYNTHETIC_APPROVED' where id='51a04000-0000-4000-8000-000000000001';
update private.signal_controls set enabled=false where tenant_id='51a02000-0000-4000-8000-000000000001';
select throws_ok($$select private.signal_record_fixture_v1(pg_temp.signal_input('global-off'))$$,'42501','signal scope unavailable','tenant global stop');
update public.tenants set outbound_messaging_enabled=true where id='51a02000-0000-4000-8000-000000000002';
select throws_ok($$select private.signal_record_fixture_v1(pg_temp.signal_input('live',1,'51a03000-0000-4000-8000-000000000003','51a02000-0000-4000-8000-000000000002'))$$,'42501','isolated signal fixture required','outbound-enabled scope denied');
select ok(not has_function_privilege('service_role','private.signal_record_fixture_v1(text)','EXECUTE'),'no service writer');
select ok(not has_function_privilege('authenticated','private.signal_record_fixture_v1(text)','EXECUTE'),'no browser writer');
select ok(not has_table_privilege('authenticated','private.signal_events','SELECT'),'no raw read');
select ok(not has_table_privilege('service_role','private.signal_events','INSERT'),'no service insert');
select ok(not has_sequence_privilege('service_role','private.signal_events_sequence_seq','USAGE'),'no sequence usage for service role');
select ok(not has_sequence_privilege('authenticated','private.signal_events_sequence_seq','UPDATE'),'no browser sequence mutation');
select is((select count(*)::int from private.verified_payment_receipts),0,'no genuine receipt');
select is((select count(*)::int from public.domain_events where event_type='payment.confirmed'),0,'no trusted payment event');
select is((select encode(extensions.digest(coalesce(jsonb_agg(to_jsonb(a) order by a.id)::text,'[]'),'sha256'),'hex') from public.channel_access a),(select hash from signal_access_baseline),'all existing access rows remain byte-for-byte unchanged');
select is((select count(*)::int from public.audit_logs where tenant_id='51a02000-0000-4000-8000-000000000001' and action='signal.synthetic_observed'),6,'one safe audit per unique event');
select * from finish();rollback;
